"""205 series - SWIs with Martabe additions (decisions agreed 2026-10-06)."""
HEAD = '''import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(CONTENT)))
from src_helpers import hazards_from
from swi_common import *
NUM = '%s'
TITLE = %r
NEW_TITLE = TITLE
NEW_JSEA = 'JSEA-PRO-MET-' + NUM
HAZARDS = %s
'''
def write(num, title, d):
    s = HEAD % ('205-' + num, title, d.get('haz', "hazards_from(os.environ['SRC_DOCX'])"))
    s += 'PPE = %s\n' % d.get('ppe', 'PPE_LAB_ACID')
    s += 'DESC = desc205(%r, %r, NUM, %r, extra_bold=%r, points=%r)\n' % (d['desc'], d['freq'], d['sc'], d.get('bold', []),
                                                                         tuple(d.get('points', ['Met lab bench - physical testwork bench and instrument'])))
    pre = ('[LAB_ALONE] + ' if d['sc'] or d.get('alone') else '') + repr(d.get('pre', []))
    steps = ["    ('Pre-start Check', PRESTART_LAB_HAZ, prestart_lab(NEW_JSEA, %s), None, %r + [PPE_EQ])," % (pre, d['equip'])]
    for t, hz, bl, cau in d['steps']:
        steps.append('    (%r, %r, %r, %r, None),' % (t, hz, bl, cau))
    steps.append('    CLOSE_LAB_STEP,')
    s += 'STEPS = [\n' + '\n'.join(steps) + '\n]\n'
    s += 'REFS = refs205(NUM, TITLE, %r)\n' % d['refs']
    s += 'EMERG = emerg(%s, %r)\n' % (d['emerg'], d.get('eqp', 'bench equipment'))
    open('content_205_%s.py' % num, 'w').write(s)

